INSERT INTO "social_media_campaigns" VALUES(2,4,1,'2025-10-16 16:21:01.530638','2025-10-16 16:21:01.530639','Roquetas de Mar - Facebook','facebook','carousel','draft','[{"type": "hero", "path": "static/campaigns/4_hero.jpg", "url": "/static/campaigns/4_hero.jpg", "index": 0}, {"type": "hotel", "path": "static/campaigns/4_hotel_0.jpg", "url": "/static/campaigns/4_hotel_0.jpg", "index": 1}, {"type": "attraction", "path": "static/campaigns/4_attraction_0.jpg", "url": "/static/campaigns/4_attraction_0.jpg", "index": 4}, {"type": "attraction", "path": "static/campaigns/4_attraction_1.jpg", "url": "/static/campaigns/4_attraction_1.jpg", "index": 5}, {"type": "itinerary", "path": "static/campaigns/4_itinerary.jpg", "url": "/static/campaigns/4_itinerary.jpg", "index": 6}, {"type": "cta", "path": "static/campaigns/4_cta.jpg", "url": "/static/campaigns/4_cta.jpg", "index": 7}]','{"instagram": "\ud83c\udf1f ROQUETAS DE MAR VOUS ATTEND ! \ud83c\udf1f\n\nD\u00e9couvrez notre offre exceptionnelle :\n\ud83d\udccd Destination : Roquetas de Mar\n\u23f1 Dur\u00e9e : 4 jours\n\ud83d\udcb0 \u00c0 partir de 800\u20ac par personne\n\n\u2728 Les points forts :\n\u2022 H\u00e9bergement en h\u00f4tel s\u00e9lectionn\u00e9\n\u2022 Visites des sites incontournables\n\u2022 Assistance francophone\n\u2022 Vols inclus\n\n\ud83d\udcf2 R\u00e9servez maintenant et vivez une exp\u00e9rience inoubliable !\n\n#VoyageRoquetasdeMar #VoyageOrganise #Tourisme #Vacances #Travel #InstaTravel #TravelGram #Wanderlust #VoyageDeLuxe #DestinationDeReve", "facebook": "\ud83c\udf0d OFFRE EXCEPTIONNELLE - Roquetas de Mar \ud83c\udf0d\n\nNous sommes ravis de vous pr\u00e9senter notre nouveau voyage organis\u00e9 vers Roquetas de Mar !\n\n\ud83d\udcc5 Dur\u00e9e : 4 jours\n\ud83d\udcb6 Prix : \u00c0 partir de 800\u20ac par personne (tout inclus)\n\nCe voyage comprend :\n\u2708\ufe0f Les vols aller-retour\n\ud83c\udfe8 L''h\u00e9bergement en h\u00f4tel de qualit\u00e9\n\ud83d\ude8c Les transferts sur place\n\ud83c\udf