CREATE TABLE social_media_templates (
	id INTEGER NOT NULL, 
	agency_id INTEGER NOT NULL, 
	name VARCHAR(100), 
	platform VARCHAR(50), 
	primary_color VARCHAR(7), 
	secondary_color VARCHAR(7), 
	font_family VARCHAR(100), 
	logo_position VARCHAR(20), 
	caption_template TEXT, 
	hashtag_template TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(agency_id) REFERENCES agency (id)
);
CREATE TABLE trip (
	id INTEGER NOT NULL, 
	agency_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	client_id INTEGER, 
	full_data_json TEXT NOT NULL, 
	hotel_name VARCHAR(200) NOT NULL, 
	destination VARCHAR(200) NOT NULL, 
	price INTEGER NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	is_published BOOLEAN, 
	published_filename VARCHAR(255), 
	is_ultra_budget BOOLEAN NOT NULL, 
	client_published_filename VARCHAR(255), 
	stripe_payment_link TEXT, 
	down_payment_amount INTEGER, 
	balance_due_date DATE, 
	document_filenames TEXT, 
	created_at DATETIME, 
	assigned_at DATETIME, 
	sold_at DATETIME, is_day_trip BOOLEAN, transport_type VARCHAR(50), bus_departure_address VARCHAR(255), travel_duration_minutes INTEGER, departure_time VARCHAR(5), return_time VARCHAR(5), payment_method VARCHAR(50), down_payment_status VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(agency_id) REFERENCES agency (id), 
	FOREIGN KEY(user_id) REFERENCES user (id), 
	FOREIGN KEY(client_id) REFERENCES client (id)
);
