INSERT INTO "trip" VALUES(7,1,3,NULL,'{"api_data": {"attractions": {}, "featured_activity": {"description": "Maastricht vous appelle ! \u2728 Laissez-vous envo\u00fbter par cette ville n\u00e9erlandaise au charme unique, o\u00f9 l''histoire et la modernit\u00e9 se rencontrent. Fl\u00e2nez dans ses ruelles pav\u00e9es, d\u00e9couvrez des boutiques originales, savourez de d\u00e9licieuses sp\u00e9cialit\u00e9s culinaires et impr\u00e9gnez-vous de son ambiance festive. Vibrez au rythme de ses \u00e9v\u00e9nements culturels, admirez ses monuments impressionnants et tombez amoureux de son cadre idyllique en bord de Meuse. Pr\u00e9parez-vous \u00e0 une exp\u00e9rience inoubliable, riche en \u00e9motions et en d\u00e9couvertes ! \ud83e\udd29", "name": "visite \u00e0 Maastricht", "photo": "https://maps.googleapis.com/maps/api/place/photo?maxwidth=800&photoreference=AWn5SU7QDXw6VmkcnoyU1ZcPMMCZhoXDi24-s0eMTxafsZJo3bHS6mXQFWHIKxm6ff_aeIMZMS9SqqALSPnof0z-iOFr1l6xEYfzqW2ICKLZtUTP5PVH5TPsAH-w2Z2zKnMi0rWLxCwYbM8H6wcIEHzGAUPe6cJx13TytKy6_rBImJp4Bm1dzprl7mOwbLaqSp8xQ7baX1CDoRYuCDpyqmHSZw8V4wHBIK-EwVTfwY5AhPECEgVVTLvOQIGa3V4IjNj580kO39B5v0akyFwqRUVFTqW08lrds5RJcDlWRzEWlhoUiuMUTZpAwwr_DCRpKjMbYL8XfoISP1SKpl9J6ocFtOQFNpYaIsOcjgjYpljaMm22jhg5rl1oF1QLzxQl8i6MKfQCJc-cfnNJnh07Xc5kLHvxU23MZknuWarc6o1ei6DUl9bUYr7R4BjDC5dBFoMCu2DHCAGEGff4z5OEgG-f7PhbIq7tLWeqHHH5Xyq51ne4d49fTr6UT1sU8OgptlrTSg4YGU_qzMh8S7dE3Q5crrSJQWTk-XXNzlux12hNzd7T0vpNxOCZF3BCAPf48qpM3lVIybqCqK8Yun_Pu0AKDSY0xhBhjw&key=AIzaSyA3RWUfHKxEAZJjkT4kFVd6F1P9_obMnr0"}, "photos": ["https://maps.googleapis.com/maps/api/place/photo?maxwidth=800&photoreference=AWn5SU4Bd-_LU00lanqGLZuz_1gCWmPfhWHFekvAoftniUAumyb6bZxow3i2XBl4dGT4XQr527VS4jhj4bpwO9aYad6Lc88gxgvawHjYEr3jB10pCn9Z0HfabtuuSrnXqDHixzJpjeacqqVabtv5HDvwiQ0HspVgsbC2M5En-F7x7zPBXIY7UA-QbYlw5QJeMD48MrXMp7ayuUuQcZeMB3CkZCW77Som3LC4vHw8q4zQOi3EImg7IdcXkkovyk0ybvueeVhuGmRSN-pPV0p17GGqALO87wF4W1J_Tf-l5arf6VtVS9AJOTYrf8AQocoL1opbQqqWjHJLDQav_qbyB4IAK8dwS71liht97uiUTwp4cCxIuDyLO60Jjy6_h-R